			case FOSSIL_ISLAND:
				return Teleports.FossilIsland.values();
			case SEAWEED:
				return Teleports.Seaweed.values();
			case ANGLERS_RETREAT:
				return Teleports.AnglersRetreat.values();
			default:
				return new TeleportOption[0];
		}
	}
}

