package com.farmrunhelper;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Highlights the option to pick in game menus: the fairy ring code, the mushtree or quetzal
 * destination, or what to say in a dialogue.
 */
class MenuHighlightOverlay extends Overlay
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(MenuHighlightOverlay.class);

	// Components to look through in each interface
	// The fairy ring travel log has a component for every code, so this covers a few hundred
	private static final int MAX_COMPONENTS = 400;

	private final Client client;
	private final FarmRunHelperPlugin plugin;
	private final FarmRunHelperConfig config;

	@Inject
	MenuHighlightOverlay(Client client, FarmRunHelperPlugin plugin, FarmRunHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightPatches())
		{
			return null;
		}
		for (MenuTarget target : plugin.getMenuTargets())
		{
			for (int group : target.getInterfaces())
			{
				Widget option = findInInterface(group, target);
				if (option == null)
				{
					logOnce(group, target);
				}
				if (option != null)
				{
					Rectangle bounds = option.getBounds();
					if (bounds != null)
					{
						OverlayUtil.renderPolygon(graphics, bounds, config.highlightColor());
					}
				}
			}
		}
		return null;
	}

	private final java.util.Set<String> logged = new java.util.HashSet<>();

	/**
	 * When a menu is open but the option can't be found, writes what its widgets say to the client log
	 * (once per menu and option), so the matching can be fixed.
	 */
	private void logOnce(int group, MenuTarget target)
	{
		Widget root = client.getWidget(group, 0);
		if (root == null || root.isHidden() || !logged.add(group + ":" + target.getText()))
		{
			return;
		}
		StringBuilder dump = new StringBuilder();
		for (int i = 0; i < MAX_COMPONENTS; i++)
		{
			dump(client.getWidget(group, i), dump, 0);
		}
		log.debug("Farm Run Helper: couldn't find \"{}\" in interface {}. Widgets: {}", target.getText(), group, dump);
	}

	private static void dump(Widget widget, StringBuilder out, int depth)
	{
		if (widget == null || depth > 2 || out.length() > 6000)
		{
			return;
		}
		String text = widget.getText();
		String name = widget.getName();
		String[] actions = widget.getActions();
		if ((text != null && !text.isEmpty()) || (name != null && !name.isEmpty()) || actions != null)
		{
			out.append("[text=").append(text).append(", name=").append(name)
				.append(", actions=").append(actions == null ? "none" : String.join("/", java.util.Arrays.stream(actions).filter(java.util.Objects::nonNull).toArray(String[]::new)))
				.append("] ");
		}
		Widget[] children = widget.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				dump(child, out, depth + 1);
			}
		}
	}

	private Widget findInInterface(int group, MenuTarget target)
	{
		for (int i = 0; i < MAX_COMPONENTS; i++)
		{
			Widget widget = client.getWidget(group, i);
			if (widget == null)
			{
				continue;
			}
			Widget found = find(widget, target, 0);
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	private static Widget find(Widget widget, MenuTarget target, int depth)
	{
		if (widget == null || widget.isHidden() || depth > 4)
		{
			return null;
		}
		if (target.matches(widget.getText()) || target.matches(widget.getName()))
		{
			return widget;
		}
		// Map icons, like on the quetzal whistle map, often only name the place in their right-click options
		String[] actions = widget.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if (target.matches(action))
				{
					return widget;
				}
			}
		}
		for (Widget[] children : new Widget[][]{widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				Widget found = find(child, target, depth + 1);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}
}

package com.farmrunhelper;

/**
 * An option to highlight in a game menu: the fairy ring code, mushtree or quetzal destination, or a dialogue option.
 */
final class MenuTarget
{
	private final int[] interfaces;
	private final String text;
	private final boolean code;

	MenuTarget(String text, boolean code, int... interfaces)
	{
		this.interfaces = interfaces;
		this.text = text.toLowerCase();
		this.code = code;
	}

	String getText()
	{
		return text;
	}

	boolean isCode()
	{
		return code;
	}

	int[] getInterfaces()
	{
		return interfaces;
	}

	/**
	 * Whether a widget's text, name or option names this target.
	 */
	boolean matches(String raw)
	{
		if (raw == null)
		{
			return false;
		}
		String plain = raw.replaceAll("<[^>]*>", "").toLowerCase();
		if (code)
		{
			// Fairy ring codes can be shown as "DKS" or "D K S"
			// Ignore labels other plugins add, like "(Shortest Path) C J Q"
			String letters = plain.replaceAll("\\(.*?\\)", "").replaceAll("[^a-z]", "");
			return letters.equals(text) || plain.matches(".*\\b" + text + "\\b.*");
		}
		return plain.contains(text);
	}
}

package com.farmrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class PatchHighlightOverlay extends Overlay
{
	private final Client client;
	private final FarmRunHelperPlugin plugin;
	private final FarmRunHelperConfig config;

	@Inject
	PatchHighlightOverlay(Client client, FarmRunHelperPlugin plugin, FarmRunHelperConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		RouteStep step = plugin.getCurrentStep();
		Player player = client.getLocalPlayer();
		if (step == null || player == null)
		{
			return null;
		}

		int plane = player.getWorldLocation().getPlane();
		Color color = config.highlightColor();
		long now = System.currentTimeMillis();
		if (config.showPath())
		{
			WorldView view = client.getTopLevelWorldView();
			Color fill = new Color(config.pathColor().getRed(), config.pathColor().getGreen(), config.pathColor().getBlue(), 50);
			for (int[] tile : plugin.getPath())
			{
				LocalPoint local = LocalPoint.fromScene(tile[0], tile[1], view);
				Polygon poly = local != null ? Perspective.getCanvasTilePoly(client, local) : null;
				if (poly != null)
				{
					OverlayUtil.renderPolygon(graphics, poly, config.pathColor(), fill, new BasicStroke(1));
				}
			}
		}
		List<Object> targets = new ArrayList<>(plugin.getHouseTargets());
		targets.addAll(plugin.getTravelTargets());
		targets.addAll(plugin.getMushtreeTargets());
		String label = plugin.getTravelLabel();
		for (Object target : targets)
		{
			Shape hull = target instanceof NPC ? ((NPC) target).getConvexHull() : hull((TileObject) target);
			if (hull != null && config.highlightPatches())
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
				if (label != null && target instanceof TileObject)
				{
					Point at = ((TileObject) target).getCanvasTextLocation(graphics, label, 100);
					if (at != null)
					{
						OverlayUtil.renderTextLocation(graphics, at, label, color);
					}
				}
			}
		}
		if (config.highlightPatches())
		{
			for (NPC squirrel : plugin.getSquirrelTargets())
			{
				Shape hull = squirrel.getConvexHull();
				if (hull != null)
				{
					OverlayUtil.renderPolygon(graphics, hull, color);
				}
				String text = "Pay to remove the tree";
				Point at = squirrel.getCanvasTextLocation(graphics, text, squirrel.getLogicalHeight() + 40);
				if (at != null)
				{
					OverlayUtil.renderTextLocation(graphics, at, text, color);
				}
			}
		}
		for (Map.Entry<GameObject, PatchType> entry : plugin.getPatchObjects().entrySet())
		{
			GameObject object = entry.getKey();
			if (object.getPlane() != plane)
			{
				continue;
			}
			WorldPoint point = object.getWorldLocation();
			PatchStatus status = plugin.getPatchStatus(point);
			if (status != null && config.growthTimers())
			{
				String text = null;
				Color textColor = Color.WHITE;
				switch (status.getKind())
				{
					case GROWING:
						if (status.getReadyAt() > 0)
						{
							text = GrowthTimes.format(status.getReadyAt() - now);
							textColor = status.getReadyAt() <= now ? Color.GREEN : Color.WHITE;
						}
						break;
					case READY:
						// No time means it's filled but when isn't known, so it may not be full yet
						text = status.getReadyAt() > 0 ? "Ready" : "Filled";
						textColor = status.getReadyAt() > 0 ? Color.GREEN : Color.YELLOW;
						break;
					case DISEASED:
						text = "Diseased";
						textColor = Color.ORANGE;
						break;
					case DEAD:
						text = "Dead";
						textColor = Color.RED;
						break;
					default:
						break;
				}
				if (text != null)
				{
					Point textLocation = object.getCanvasTextLocation(graphics, text, entry.getValue().isTree() ? 250 : 80);
					if (textLocation != null)
					{
						OverlayUtil.renderTextLocation(graphics, textLocation, text, textColor);
					}
				}
			}
			// Only the patch to plant next is highlighted
			if (!config.highlightPatches() || object != plugin.getNextPatch())
			{
				continue;
			}
			Shape hull = object.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
		return null;
	}

	private static Shape hull(TileObject object)
	{
		Shape shape = null;
		if (object instanceof GameObject)
		{
			shape = ((GameObject) object).getConvexHull();
		}
		else if (object instanceof DecorativeObject)
		{
			shape = ((DecorativeObject) object).getConvexHull();
		}
		else if (object instanceof WallObject)
		{
			shape = ((WallObject) object).getConvexHull();
		}
		return shape != null ? shape : object.getClickbox();
	}
}

